query GetCategoryPostIds($slug: ID!, $first: Int!) {
  category(id: $slug, idType: SLUG) {
    databaseId
    name
    slug
    description
    count
    posts(first: $first) {
      nodes {
        databaseId
        date
        __typename
      }
      __typename
    }
    __typename
  }
}
